/* Binary search: returns token_id for a unicode codepoint, or 3 (UNK) if not found. */
static int v10_lookup_token(uint32_t cp) {
    int lo = 0, hi = V10_TOKEN_MAP_SIZE - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (v10_token_map[mid].cp == cp) return v10_token_map[mid].token_id;
        if (v10_token_map[mid].cp < cp) lo = mid + 1;
        else hi = mid - 1;
    }
    return 3; /* UNK */
}

